#include <iostream>
#include <vector>
#include <string>

using namespace std;

/**
 * 題目 10418: Minesweeper
 * 經典踩地雷數字生成：
 * 給定一個 M x N 的地圖，其中 '*' 代表地雷，'.' 代表安全區。
 * 將安全區替換為周圍 8 個格子中地雷的數量。
 */

int main() {
    int n, m, fieldNum = 1;
    while (cin >> n >> m && (n != 0 || m != 0)) {
        if (fieldNum > 1) cout << endl;
        vector<string> grid(n);
        for (int i = 0; i < n; ++i) cin >> grid[i];

        cout << "Field #" << fieldNum++ << ":" << endl;
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < m; ++j) {
                if (grid[i][j] == '*') {
                    cout << '*';
                } else {
                    int count = 0;
                    // 檢查周圍 8 個方位
                    for (int di = -1; di <= 1; ++di) {
                        for (int dj = -1; dj <= 1; ++dj) {
                            int ni = i + di;
                            int nj = j + dj;
                            if (ni >= 0 && ni < n && nj >= 0 && nj < m && grid[ni][nj] == '*') {
                                count++;
                            }
                        }
                    }
                    cout << count;
                }
            }
            cout << endl;
        }
    }
    return 0;
}
